"""Regression coverage for deep-review oracle routing."""

import ask.ask_results as ask_results


def test_deep_review_bypasses_generic_parallel_moderator(monkeypatch):
    captured = {}

    def fake_apply_oracle_synthesis(result, **kwargs):
        captured.update(kwargs)
        result["answer"] = "deep review answer"
        result["oracle"] = {
            "model": kwargs["model"],
            "reasoning_effort": kwargs["reasoning_effort"],
            "backend": kwargs["backend"],
        }

    monkeypatch.setattr(ask_results, "_apply_oracle_synthesis", fake_apply_oracle_synthesis)
    monkeypatch.setattr(ask_results, "finalize_deep_review_result", lambda result, request: {})

    ask_results._synthesise(
        {
            "question": "deep review this",
            "scope": "ask",
            "items": [],
            "bridges_found": [],
            "answer": "",
        },
        k=5,
        raw=False,
        as_json=True,
        auto_learn=False,
        oracle_model="gpt-5.5",
        oracle_reasoning="high",
        oracle_backend="subagent-runner",
        parallel_review=True,
        parallel_reviewers=3,
        parallel_review_focus="safety",
        deep_review_request={
            "target": {
                "target": "target.md",
                "target_bundle": {
                    "entries": [
                        {
                            "source_id": "TARGET.1",
                            "kind": "file",
                            "path": "target.md",
                            "content": "target content",
                            "truncated": False,
                        }
                    ]
                },
            },
            "original_question": "deep review this",
            "profile": "max_available",
            "reviewers": 3,
            "focus": "safety",
            "dogpile_mode": "off",
        },
    )

    assert captured["parallel_review"] is False
    assert captured["parallel_reviewers"] == 3
    assert captured["parallel_review_focus"] == "safety"
